-- Homestead: Fallout 4's workshop in Cyberpunk 2077. V founds a settlement anywhere (a workbench; CET hotkey). Tap F at its bench, or hold F
-- anywhere in it, for workshop mode: a Fallout-style menu of catalog pieces (catalog.lua, generated by tools/build_catalog.py). Pieces are Codeware
-- dynamic entities saved with the game (persistSpawn), spawned from homestead\empty.ent; their tags say what they are, the entity's own transform
-- where. Meshes and colliders are added on Entity/Initialize (the reds hand every such entity to onEntity). Controls are Fallout 4's PC workshop.
-- The zone is the circle of RADIUS round the settlement's centre; in workshop mode a holographic wall shows it.
-- This file is the wiring and the frame loop: catalog index, constants, state (S), the table every module shares (C), workshop mode, input (onKey),
-- the frame (update), sessions, console commands. The rest is in modules/, required in this order: engine, geometry, entities, placement, support,
-- ui, command, sites, anim, gizmo, border, life (navigation, livenav), testing, settings.

local okCat, catalog = pcall(require, "catalog")              -- (none before the first import: nothing to build yet,
if not okCat or type(catalog) ~= "table" then                 -- the settings still work; CET's require gives nil for a
    catalog = { categories = {}, items = {}, sounds = {} }     -- missing file, no error)
end
for i = #catalog.items, 1, -1 do
    if catalog.items[i].key == "boundary" then table.remove(catalog.items, i) end
end
-- People's animations (modules/own/poses.lua) are cards of a tab of their own, Animations: one "placed" on a person gives it to them
-- (placement.lua place).
for _, x in ipairs((#catalog.items > 0 and not catalog.posed) and require("modules/own/poses") or {}) do   -- (no import: no menu; once)
    catalog.posed = true
    catalog.items[#catalog.items + 1] = { key = "pose_" .. x.id, name = x.name, group = x.group, cat = "Animations", pose = x.id, apps = { "default" },
                                          min = { -0.2, -0.2, 0 }, max = { 0.2, 0.2, 0.4 }, base = { 0, 0, 0 }, nmesh = 0, nent = 0 }
end
-- Night City's own working things (modules/own/devices.lua) are cards of the Night City tab: the game's device entity itself
-- is what is placed (and what is held: no preview of ours), as a weapon's template is.
for _, x in ipairs((#catalog.items > 0 and not catalog.deviced) and require("modules/own/devices") or {}) do
    if not catalog.deviced then                               -- (once: the plain props these stand in for, out of the menu)
        for _, it in ipairs(catalog.items) do
            for _, pat in ipairs(it.cat == "Night City" and require("modules/own/devices").hide or {}) do
                if it.name:lower():find(pat) then it.hidden = true end
            end
        end
    end
    catalog.deviced = true
    local w, d, h = x.size[1], x.size[2], x.size[3]
    catalog.items[#catalog.items + 1] = { key = "dev_" .. x.id, name = x.name, group = x.group, cat = "Night City", device = true,
                                          template = "base\\gameplay\\devices\\" .. x.ent .. ".ent", apps = x.apps or { "default" },
                                          min = { -w / 2, -d / 2, 0 }, max = { w / 2, d / 2, h }, base = { 0, 0, 0 }, nmesh = 0, nent = 1 }
end
-- an item's heavy fields (build_catalog.py HEAVY: colliders, meshes, snap points, animations...) live in
-- data/catalog_<dat>.lua, loaded the first time any of them is read - its whole menu folder at once. Startup and the
-- menu read catalog.lua alone.
do
    local HEAVY = { boxes = true, cboxes = true, pcol = true, anim = true, connect = true, meshes = true, ents = true,
                    lights = true, fx = true, snd = true, seats = true, profile = true }
    local byDat = {}
    -- What the mod owns, over what the import says (modules/own/<field>.lua: key -> value, false: none). The import's
    -- is kept for a piece not listed there (one a player's Fallout mod adds): an update changes these with no import.
    local OWN = {}
    for _, f in ipairs({ "lights", "seats", "snd", "fx" }) do OWN[f] = require("modules/own/" .. f) end
    local STASH, MENU = require("modules/own/stash"), require("modules/own/menu")
    local STASH_ENTS = { { path = "base\\gameplay\\devices\\stash\\stash.ent", app = "default", x = 0, y = 0, z = 0, q = { 0, 0, 0, 1 } } }
    for _, it in ipairs(catalog.items) do
        if STASH[it.key] ~= nil then it.stash = STASH[it.key] or nil end
        for f, v in pairs(MENU[it.key] or {}) do it[f] = v end
    end
    for _, it in ipairs(catalog.items) do if it.dat then byDat[it.dat] = byDat[it.dat] or {}; table.insert(byDat[it.dat], it) end end
    local meta = {}
    local LISTS = { boxes = true, meshes = true }             -- (never nil: a weapon has no boxes - every check counts them)
    function meta.__index(it, k)
        if not HEAVY[k] then return nil end
        local n = rawget(it, "dat")
        if not n or not byDat[n] then
            if LISTS[k] then rawset(it, k, {}) return rawget(it, k) end
            return nil
        end
        local ok, d = pcall(require, "data/catalog_" .. n)   -- (CET caches it; its tables are the items' own now)
        local its = byDat[n]
        byDat[n] = nil
        for _, x in ipairs(its) do
            for f, v in pairs(ok and type(d) == "table" and d[x.key] or {}) do rawset(x, f, v) end
            for f, own in pairs(OWN) do
                if own[x.key] ~= nil then rawset(x, f, own[x.key] or nil) end
            end
            if STASH[x.key] ~= nil then rawset(x, "ents", STASH[x.key] and STASH_ENTS or nil) end
        end
        if rawget(it, k) == nil and LISTS[k] then rawset(it, k, {}) end
        return rawget(it, k)
    end
    for _, it in ipairs(catalog.items) do setmetatable(it, meta) end
end

-- settlements are where V founds them (a workbench); away from all of them, S.zone is NOWHERE (nothing to build in)
-- A settlement: this far round its centre (m), always a circle.
-- Settings > Building > Settlement size, read here because the modules take it as they load.
local SET = ""
do local f = io.open("settings.txt", "r") if f then SET = f:read("*a"); f:close() end end
local RADIUS = tonumber(SET:match("%f[%w]radius=(%d+)")) or 50
local NOWHERE = { x = -1e6, y = -1e6, z = 0, key = "none" }
local GRID, STOREY = 3.0, 4.0 -- the Badlands building kit: 3 m cells, 4 m storeys
local REACH = 25              -- how far the crosshair reaches (m)
local BUDGET = 8000
local ENT_COST = 10           -- a game object a building brings (a door, a lamp: its own entity, a light) costs as much as 10 meshes
local HOLD_F = 0.6
local KEYS = {
    act = "IK_E", act2 = "IK_Enter", scrap = "IK_R", back = "IK_Tab", free = "IK_Q", hold = "IK_F", command = "IK_R",
    left = "IK_Left", right = "IK_Right", down = "IK_Down", up = "IK_Up",
    rotL = "IK_LeftMouse", rotR = "IK_RightMouse", gizmo = "IK_LControl", far = "IK_MouseWheelUp", near = "IK_MouseWheelDown",
}
local PUSH = { step = 0.15, min = 0.25, big = 3, near = 0.5 } -- a wheel notch moves the held piece by step of its distance
                                                              -- (at least min m; Shift: big times that); nearest near m
local SPIN = 90
local REPEAT = { delay = 0.35, rate = 0.08, fast = 0.03, after = 1.5 }
local SFX = {                  -- the game's own sound events (base\sound\event\eventsmetadata.json)
    enter = "ui_hacking_access_granted", exit = "ui_hacking_close",
    tab = "ui_gui_tab_change", move = "ui_menu_hover", open = "ui_menu_onpress", back = "ui_menu_close",
    build = { "lcm_fs_heavy_boots_concrete_land", "lcm_fs_heavy_boots_tarmac_land" },
    drop = { "cmn_generic_work_small_object_drop", "lcm_fs_heavy_boots_dirt_land" },
    grab = "cmn_generic_cardboard_pick_up", scrap = "ui_menu_item_disassemble", refuse = "ui_menu_item_crafting_fail",
    turn = "ui_menu_scrolling_stop",
}
local OUTLINE = { off = 0, valid = 1, invalid = 2, target = 5, usable = 1, selected = 2 }

local CHUNK = 100             -- meshes per entity: 141 were fine, 240 took the game down; big buildings are split
local byKey = {}
-- Settings > Mods > Homestead > Fallout 4 pieces / Night City pieces, off: theirs leave the menu (ones placed stay)
local OFF = { fo4 = SET:find("%f[%w]importFo4=0") ~= nil, nc = SET:find("%f[%w]importNC=0") ~= nil }
for i, it in ipairs(catalog.items) do
    if it.npc and TweakDB and not TweakDB:GetRecord(it.record) then it.hidden = true end
    if (OFF.fo4 and it.fo4) or (OFF.nc and it.cat == "Night City") then it.hidden = true end
    it.cx, it.cy = (it.min[1] + it.max[1]) / 2, (it.min[2] + it.max[2]) / 2
    it.size = { it.max[1] - it.min[1], it.max[2] - it.min[2], it.max[3] - it.min[3] }
    byKey[it.key] = it
    it.chunks = math.max(1, math.ceil(it.nmesh / CHUNK))
    it.cost = it.nmesh + ENT_COST * it.nent
end

-- state ------------------------------------------------------------------------------------------------------------

local S = {
    zone = NOWHERE,              -- the settlement V is at (the nearest: Sites.nearest), NOWHERE away from them all
    build = false, overlay = false,
    level = 0,                   -- workshop menu: 0 = category tabs; n = the row of kids of the node n - 1 levels down
    cat = 1, sel = {},           -- the category; the selected kid of each node (node -> index)
    hold = nil,                  -- { kind = "new"|"move", key, app, yaw, flip, orig }
    free = false,                -- free placement for kit pieces too
    dist = nil, rot = 0,         -- the wheel's distance to the held piece (nil: the aim's); rotate button held (1 / -1)
    slot = nil,                  -- the last snapped slot (hysteresis)
    ghost = nil,                 -- { id, key, app, outline, t, o, yaw, placed }
    pieces = {}, bench = nil, target = nil,
    byId = {},                   -- entity id hash -> its piece (S.pieces by id)
    world = 0,                   -- the zone's built pieces' version: bumped on any change (entities.lua)
    occupied = {}, levels = {},
    ring = nil,                  -- the border's wall while shown: { id, h, zone } (modules/border.lua)
    toast = nil, toastT = 0,
    pending = {},                -- entity id hash -> { key, app, ghost, bench, o, yaw } for pieces spawned this session
    seenIds = {},                -- the ids refresh read last (the periodic one's cheap path: the same ones again?)
    info = {},                   -- entity id hash -> tag info (or false), see tagInfo
    fHeld = false, fTime = 0, fUsed = false,
    cHeld = false, cTime = 0, cUsed = false,
    nearBench = false, inZone = false, pins = {}, siteT = 0, refreshT = 0, fx = {}, after = {}, hinted = {}, orphan = {}, nostash = {}, anims = {}, playing = {}, sfx = {}, running = {}, dark = {}, cyc = {},
    cost = 0,                    -- the zone's pieces' mesh count, against BUDGET
    checked = {},                -- entity id hash -> true once a placed person's attitude to V was checked
    unloaded = {},               -- entity id hash -> true while its settlement is out of the world (sites.lua: by distance)
}


local atan2 = math.atan2 or math.atan                    -- LuaJIT (CET) has atan2; Lua 5.3+ has a 2-argument atan
local World = {}                                             -- (modules/world.lua: the dynamic entity system, and the static one
local function des() return World end                        -- for our own pieces, under one set of names)
local function v4(x, y, z) return Vector4.new(x, y, z, 1) end
local function hashOf(id) return tostring(id.hash) end
local function say(text) S.toast, S.toastT = text, 3 end
local function log(text) print("[Homestead] " .. text) end
local warned = {}
local function try(what, f, ...)
    local ok, e = pcall(f, ...)
    if ok then return e end
    if not warned[what] then warned[what] = true; log(what .. " failed: " .. tostring(e)) end
end
-- C: what init.lua and the modules share - state, helpers, constants and each other's tables and functions. A module
-- (modules/*.lua, required below in order) takes what it uses from C and puts what it makes into C; what it calls
-- in a module loaded after it, it reaches through C when it calls.
local C = { S = S, catalog = catalog, byKey = byKey, atan2 = atan2, des = des, v4 = v4, hashOf = hashOf, say = say,
            log = log, try = try, NOWHERE = NOWHERE, RADIUS = RADIUS, GRID = GRID, STOREY = STOREY, REACH = REACH,
            BUDGET = BUDGET, KEYS = KEYS, SFX = SFX, OUTLINE = OUTLINE, CHUNK = CHUNK,
            Eng = {}, Anim = {}, Gizmo = {}, Border = {}, Testing = {}, Life = {}, Settings = {}, Turret = {}, Elevator = {}, Ball = {} }
local function sfx(name)
    if type(name) == "table" then for _, n in ipairs(name) do pcall(Homestead.Sound, n) end else pcall(Homestead.Sound, name) end
end
local function playerPos() local p = Game.GetPlayer(); return p and p:GetWorldPosition() end
C.sfx, C.playerPos = sfx, playerPos
local Eng, Anim, Gizmo = C.Eng, C.Anim, C.Gizmo
local Border, Testing, Life, Settings = C.Border, C.Testing, C.Life, C.Settings
function C.inGame()
    local ok, pre = pcall(function() return Game.GetSystemRequestsHandler():IsPreGame() end)
    if ok then return not pre end
    return playerPos() ~= nil
end
function C.applied()
    Life.allow.walk, Life.allow.furniture, Life.allow.talk = Settings.on("peopleWalk"), Settings.on("peopleFurniture"), Settings.on("peopleTalk")
    Life.allow.nav = Settings.on("peopleNav")
    S.showSnaps, S.showBorder = Settings.on("snapPoints"), Settings.on("borderLine")
    S.loadDist = Settings.num("loadDistance")
    Border.update()
end

require("modules/world")(World, C)
require("modules/engine")(Eng, C)
local timed = C.timed

require("modules/geometry")(C)
local Q, zoneDist, Grid, aim, pairs_ = C.Q, C.zoneDist, C.Grid, C.aim, C.pairs_

require("modules/entities")(C)
local del, removePiece, afterAttach, onEntity, outlinePiece, retarget, refresh =
    C.del, C.removePiece, C.afterAttach, C.onEntity, C.outlinePiece, C.retarget, C.refresh

require("modules/placement")(C)
local placement, aimAt, holdDistance, snapDots, dropGhost, syncGhost, restore, place, startMove, scrap =
    C.placement, C.aimAt, C.holdDistance, C.snapDots, C.dropGhost, C.syncGhost, C.restore, C.place, C.startMove,
    C.scrap

require("modules/support")(C)

require("modules/ui")(C)
local tree, CATS, root, picked, syncHold, Lines, plant, plantLines, benchPrompt, Keys, usePrompt, syncUI =
    C.tree, C.CATS, C.root, C.picked, C.syncHold, C.Lines, C.plant, C.plantLines, C.benchPrompt, C.Keys, C.usePrompt,
    C.syncUI

require("modules/command")(C)
local Cmd = C.Cmd

require("modules/sites")(C)
local Sites, pin, found, abandon =
    C.Sites, C.pin, C.found, C.abandon

require("modules/anim")(Anim, C)
World.gone = Anim.forget
require("modules/turret")(C.Turret, C)
require("modules/elevator")(C.Elevator, C)
require("modules/ball")(C.Ball, C)
require("modules/gizmo")(Gizmo, C)
require("modules/border")(Border, C)
require("modules/life")(Life, C)
