Settings.apply()


local function enterBuild()
    if S.build then return end
    if #catalog.items == 0 then say("Nothing to build yet: import Fallout 4 in Homestead's settings"); sfx(SFX.refuse) return end
    Cmd.exit()
    S.build = true
    Homestead.Restrict(true)
    S.nearBench = false
    refresh(true)
    Border.update()
    S.hold, S.level, S.dist, S.rot, S.slot = nil, 0, nil, 0, nil
    local told = S.toldNewer                                -- (the offer: once a session)
    S.toldNewer = true
    say(Settings.stale() and "Homestead was updated: import again from the main menu (Settings > Mods > Homestead)"
        or not told and Settings.newer() and "Homestead: a new version's data is ready - import again when you like (Settings > Mods > Homestead)"
        or "Workshop mode")
    sfx(SFX.enter)
end

local function exitBuild()
    if not S.build then return end
    Gizmo.off()
    if S.hold and S.hold.kind == "move" then restore() end
    S.hold, S.level, S.rot = nil, 0, 0
    dropGhost()
    if S.target then outlinePiece(S.target, OUTLINE.off) end
    Lines.set("plant", nil); Lines.set("snap", nil)
    S.target = nil
    S.build = false
    Border.update()
    Homestead.Restrict(false)
    sfx(SFX.exit)
end
C.exitBuild = exitBuild

local frame, wheelFrame = 0, -1
-- a menu or CET's overlay has the keyboard: whatever was held counts as let go (its release comes to the menu, not here:
-- a held F stayed held and toggled workshop mode by itself), a rotation or a gizmo drag ends as on a release
local function releaseKeys()
    S.fHeld, S.fUse, S.cHeld, S.repeatKey, S.shiftDown, S.rot = false, nil, false, nil, false, 0
    if S.gz then Gizmo.press(false); Gizmo.look(false) end
end
local function onKey(key, down, shift, rep)
    if S.overlay or Homestead.InMenu() then releaseKeys() return end
    if not rep and (key == KEYS.left or key == KEYS.right) then
        if down then S.repeatKey, S.repeatT, S.repeatAcc = key, 0, 0 elseif S.repeatKey == key then S.repeatKey = nil end
    end
    if key == KEYS.hold then
        if down and not S.fHeld then
            S.fHeld, S.fTime, S.fUsed = true, 0, false
            S.fUse = not S.build and S.use or nil
            if not S.build and S.nearBench then enterBuild(); S.fUsed = true end
        elseif not down then
            if S.fUse and not S.fUsed and S.fTime < HOLD_F then Anim.use(S.fUse) end
            S.fHeld, S.fUse = false, nil
        end
        return
    end
    if key == KEYS.command and (S.cmd or not S.build) then
        if down and not S.cHeld then S.cHeld, S.cTime, S.cUsed = true, 0, false
        elseif not down then
            if S.cmd and S.cHeld and not S.cUsed and S.cTime < HOLD_F then Cmd.clear() end
            S.cHeld = false
        end
        return
    end
    if key == "IK_LShift" or key == "IK_RShift" then S.shiftDown = down end
    if S.cmd then
        if down and not rep then
            if key == KEYS.act or key == KEYS.act2 then Cmd.act()
            elseif key == KEYS.scrap then Cmd.clear()
            elseif key == KEYS.back then Cmd.unselect() end
        end
        return
    end
    if not S.build then                                       -- (the hand on an elevator's button: a click presses it, as F does)
        if S.hand and S.use and down and not rep and key == KEYS.rotL then Anim.use(S.use) end
        return
    end
    local h = S.hold
    if key == KEYS.gizmo then
        if down then
            if S.gz and h and h.kind == "move" then place(); sfx(SFX.back)
            elseif S.gz then Gizmo.off(); sfx(SFX.back)
            elseif h then S.free = true; Gizmo.on()
            elseif S.target and not S.target.bench then
                local p = S.target
                -- (a person isn't taken up: the gizmo moves them as they are - placement.lua gizmoPickup)
                if (p.it.npc and C.gizmoPickup(p)) or (not p.it.npc and startMove(p)) then S.free = true; Gizmo.on(p.o) end
            end
        end
        return
    end
    if S.gz and (key == KEYS.rotL or key == KEYS.rotR) then
        if key == KEYS.rotL then Gizmo.press(down) else Gizmo.look(down) end
        return
    end
    if key == KEYS.rotL or key == KEYS.rotR then
        local sgn = key == KEYS.rotL and 1 or -1
        if not down then
            if S.rot == sgn then S.rot = 0 end
        elseif h and not S.free and byKey[h.key].fo4 and not byKey[h.key].kind then
            if S.joined and (S.ties or 0) > 1 then S.tie = ((S.tie or 0) + sgn) % S.ties; sfx(SFX.turn)
            else S.rot = sgn end
        elseif h and not S.free and byKey[h.key].kind then
            if byKey[h.key].kind == "wall" then h.flip = not h.flip else h.yaw = (h.yaw + 90 * sgn) % 360 end
            sfx(SFX.turn)
        elseif h then
            S.rot = sgn
        end
        return
    end
    if not down then return end
    if key == KEYS.far or key == KEYS.near then
        if wheelFrame == frame then return end
        wheelFrame = frame
        if S.gz then Gizmo.wheel(key == KEYS.far and 1 or -1); sfx(SFX.turn); return end
        if h then
            local it = byKey[h.key]
            local held = it.connect and not S.free and C.holdDepth(it)
            local r = not S.dist and not S.free and not held and aimAt()
            local now = S.dist or held or ((S.free or r.sky) and holdDistance(it)) or math.sqrt((r.p.x - r.eye.x) ^ 2 + (r.p.y - r.eye.y) ^ 2 + (r.p.z - r.eye.z) ^ 2)
            local step = math.max(PUSH.min, now * PUSH.step) * (shift and PUSH.big or 1) * (key == KEYS.far and 1 or -1)
            S.dist = held and math.max(held, math.min(1024 * C.U, now + step)) or math.max(PUSH.near, math.min(REACH, now + step))
            sfx(SFX.turn)
        end
        return
    end
    if key == KEYS.free then
        Gizmo.off()
        S.free = not S.free
        S.slot = nil
        if h and not S.free and not byKey[h.key].fo4 then h.yaw = Q.square(h.yaw) end
        say(S.free and "Free placement" or "Snap placement")
        sfx(SFX.open)
        return
    end
    if h and h.kind == "move" then
        if key == KEYS.act or key == KEYS.act2 then place()
        elseif key == KEYS.scrap then scrap()
        elseif key == KEYS.back then restore() end
        return
    end
    local e, n = picked()
    if #root().kids == 0 and key == KEYS.down then return end
    if key == KEYS.left or key == KEYS.right then
        local d = key == KEYS.right and 1 or -1
        if S.level == 0 then
            local c = math.max(1, math.min(#CATS, S.cat + d))
            if c ~= S.cat then S.cat = c; sfx(SFX.tab) end
        else
            local i = math.max(1, math.min(#n.kids, (S.sel[n] or 1) + d))
            if i ~= (S.sel[n] or 1) then S.sel[n] = i; sfx(SFX.move) end
        end
        syncHold()
    elseif (key == KEYS.down or key == KEYS.act2) and (S.level == 0 or not e.key) then
        S.level = S.level + 1
        sfx(SFX.open)
        syncHold()
    elseif (key == KEYS.act or key == KEYS.act2) and S.hold then place()
    elseif key == KEYS.act and S.target then startMove(S.target)
    elseif key == KEYS.scrap and S.target and not S.hold then scrap()
    elseif key == KEYS.up or key == KEYS.back then
        if S.level > 0 then S.level = S.level - 1; sfx(SFX.back); syncHold()
        elseif key == KEYS.back then exitBuild() end
    end
end


local function session(start)
    World.forget()
    Life.reset(true)
    Life.navClear(true)
    Life.choose()
    Eng.forget()
    if S.build and not start then Homestead.Restrict(false) end
    S.build = false
    S.info = {}
    S.pending, S.pieces, S.byId, S.bench, S.target, S.ghost, S.hold, S.slot = {}, {}, {}, nil, nil, nil, nil, nil
    S.world, S.ring = S.world + 1, nil
    S.pins, S.hinted, S.hintSig, S.useShown, S.nearBench, S.fHeld, S.hand = {}, {}, nil, false, false, false, false
    S.menuSig, S.seenIds, S.settled, S.targetShown, S.waitIds, S.checked = nil, {}, nil, nil, {}, {}
    S.unloaded = {}
    Sites.reset()
    Lines.by, Lines.dirty = {}, false
    if start then Homestead.Restrict(false) end            -- a save made in workshop mode keeps the restriction
end

registerForEvent("onInit", function()
    pcall(Settings.init)
    Life.choose()
    Observe("HomesteadService", "HomesteadEntity", function(_, entity) timed("dress", onEntity, entity) end)   -- (clocked: a
                                                             -- piece dressed costs - sites.lua spreads them by distance)
    Observe("HomesteadService", "HomesteadKey", function(_, key, down, shift) onKey(key, down, shift) end)
    Observe("HomesteadService", "HomesteadMouse", function(_, dx, dy) Gizmo.mouse(dx, dy) end)
    Observe("HomesteadService", "HomesteadSession", function(_, start) session(start) end)
    Observe("HomesteadService", "HomesteadSaved", function() World.saved() end)
    -- An import to do (the first, a needed one, or one offered: settings.lua): the game's own message box on the main
    -- menu says so, once a session (Homestead.reds HomesteadNotice). The import itself is the settings': its progress is there.
    local WHERE = "\n\nOpen Settings > Mods > Homestead and press Import. Its progress shows there."
    pcall(Settings.update)                                       -- (asks now: the answer is there by the time the menu is up)
    ObserveAfter("SingleplayerMenuGameController", "OnInitialize", function(self)
        local msg = Settings.first() and "Homestead makes its Fallout 4 pieces from your own Fallout 4 before first use. It takes about 15-20 minutes, once." .. WHERE
            or Settings.stale() and "Homestead was updated and needs its import run again. Only what changed is redone." .. WHERE
            or Settings.newer() and Settings.get("seenBuild") ~= Settings.buildId() and "This version of Homestead has new data for you. It is optional: the mod works as it is, and only what changed is redone." .. WHERE
        S.noticeSeen = msg and not Settings.first() and not Settings.stale() and { "seenBuild", Settings.buildId() } or nil
        local tag = not msg and Settings.update()                -- (nothing to import: a newer release, if GitHub has one)
        if tag and Settings.get("seenRelease") == tag then tag = nil end
        if tag then S.noticeSeen = { "seenRelease", tag } end       -- (an offer is made once: closed, not again for that build / release - user)
        if tag then msg = "Homestead " .. tag .. " is out (you have " .. tostring(Settings.version()) .. ").\n\nGet it from github.com/shawn-makes-stuff/homestead/releases" end
        if S.toldImport or not msg then return end
        -- (told once the player has closed it: the menu's controller is made more than once as the game starts, and a
        -- box dies with the one that showed it - seen 2026-10-05: no box, no error)
        try("notice", function() Homestead.Notice(self, "Homestead", msg) end)
        log("import notice shown")
    end)
    -- (the menu's own method: a static one of ours wasn't found - the log, 2026-10-05: "Function NoticeClosed in class
    -- Homestead does not exist" - so a closed box was never known closed, and an offer never remembered as made)
    Observe("SingleplayerMenuGameController", "OnHomesteadNoticeClosed", function()
        S.toldImport = true
        if S.noticeSeen then Settings.set(S.noticeSeen[1], S.noticeSeen[2]) end
    end)
    log("loaded, " .. #catalog.items .. " pieces in the catalog")
end)

registerForEvent("onOverlayOpen", function() S.overlay = true; releaseKeys() end)
registerForEvent("onOverlayClose", function() S.overlay = false end)

local function setZone(z)
    z = z or NOWHERE
    if z == S.zone then return end
    exitBuild()
    Life.reset()
    S.zone, S.level = z, 0
    Life.navZone(z)
    refresh()
end
C.setZone = setZone

-- the frame: the toast, the settlements (every 2 s), what's attaching and animating, the fall guard, the
-- settlement V is at; people (every second; their walks every frame), held arrows and keys timed; then one of:
-- Command mode, out of workshop mode (the bench and use prompts), workshop mode (the held piece's turn,
-- the gizmo, placement, the preview, snap points - or the piece looked at)
local function update(dt)
    frame = frame + 1
    S.frameDt = dt
    S.cam = nil
    if S.popwatch then Testing.popTick(dt) end
    if S.toast then S.toastT = S.toastT - dt; if S.toastT <= 0 then S.toast = nil end end
    local pos = playerPos()
    pcall(Settings.tick, dt)                                -- (Settings > Mods > Homestead: the importer's news, the
    if not pos or not des() or not des():IsReady() then return end   -- main menu too - the import starts from there)
    World.tick(dt)
    S.siteT = S.siteT - dt
    if S.siteT <= 0 then
        S.siteT = 2
        Sites.scan()
        for _, s in ipairs(Sites.list) do if S.pins[s.key] == nil then pin(s) end end
    end
    if #S.after > 0 then timed("attach", afterAttach, dt) end
    if next(S.playing) then timed("animation", Anim.tick, dt) end
    if S.stashOpen then Anim.stashTick(dt) end
    -- workshop mode: no fall damage - V can't be hurt while dropping (on when falling fast, off a second after landing)
    local vz = S.lastZ and (pos.z - S.lastZ) / math.max(dt, 1e-3) or 0
    S.lastZ = pos.z
    if S.build and vz < -3 and vz > -200 and not S.unhurt then S.unhurt = 0; pcall(Homestead.Unhurt, true) end
    if S.unhurt then
        S.unhurt = math.abs(vz) < 0.5 and S.unhurt + dt or 0
        if S.unhurt > 1 then S.unhurt = nil; pcall(Homestead.Unhurt, false) end
    end
    setZone(Sites.nearest(pos))
    timed("stream", Sites.stream, dt, pos)
    local out = zoneDist(pos.x, pos.y)
    local near = out < 250
    if near then timed("turrets", C.Turret.tick, dt, pos); timed("elevators", C.Elevator.tick, dt); timed("balls", C.Ball.tick, dt, pos) end
    if S.calm then C.calm(dt) end
    S.inZone = out < 5
    S.refreshT = S.refreshT - dt
    if S.refreshT <= 0 then
        S.refreshT = 1
        if near then
            timed("near", Anim.near, pos)
            if not S.build then timed("refresh", refresh, true) end
            if S.build and Life.sync() then Grid.build(S.pieces) end
        end
    end
    if near then timed("remake", C.remake) end
    timed("life", Life.step, dt, not near)
    if near then timed("walk", Life.frame, dt) end
    if S.repeatKey then
        S.repeatT = S.repeatT + dt
        if S.repeatT >= REPEAT.delay and S.build then
            S.repeatAcc = S.repeatAcc + dt
            local rate = S.repeatT > REPEAT.after and REPEAT.fast or REPEAT.rate
            local n = 0
            while S.repeatAcc >= rate and n < 4 do S.repeatAcc, n = S.repeatAcc - rate, n + 1; onKey(S.repeatKey, true, false, true) end
        end
    end
    if S.fHeld and not S.fUsed then
        S.fTime = S.fTime + dt
        if S.fTime >= HOLD_F then
            S.fUsed = true
            if S.build then exitBuild() elseif S.inZone then enterBuild() end
        end
    end
    if S.cHeld and not S.cUsed then
        S.cTime = S.cTime + dt
        if S.cTime >= HOLD_F then
            S.cUsed = true
            if S.cmd then Cmd.exit() elseif S.inZone and Life.walks() then Cmd.enter() end
        end
    end
    local okUI, errUI = pcall(timed, "ui", syncUI)
    if not okUI and not S.uiErr then S.uiErr = true; log("ui: " .. tostring(errUI)) end
    if S.hand and (S.cmd or S.build) then S.hand = false; pcall(Homestead.Hand, false) end
    if S.cmd then timed("command", Cmd.tick, dt) return end
    if not S.build then
        if near then benchPrompt(pos) else S.nearBench = false end
        S.use, S.useLabel = nil, nil
        local handy = false
        if near and frame % 3 == 0 then
            if S.usableWorld ~= S.world then                    -- (what V can use: listed anew only when the pieces change)
                S.usableWorld, S.usable = S.world, {}
                for _, p in ipairs(S.pieces) do if Anim.usable(p.it) then S.usable[#S.usable + 1] = p end end
            end
            for _, p in ipairs(S.usable) do
                if (p.o.x - pos.x) ^ 2 + (p.o.y - pos.y) ^ 2 < 64 then handy = true break end
            end
        end
        -- An elevator's button under the crosshair, on whatever floor: the game's own hand, as on its elevators' panels
        -- (user, 2026-10-05: not our F prompt) - a click or F presses it. Kept up each frame it is there, let go once.
        local ep, el = C.Elevator.hover(pos)
        if ep or S.hand then pcall(Homestead.Hand, ep ~= nil) end
        S.hand = ep ~= nil
        if ep then S.use, S.useLabel, S.useT = ep, el, 0
        elseif handy then
            local a = aim()
            local lb = a.piece and a.t < 3.5 and Anim.usable(a.piece.it) and Anim.label(a.piece)
            if lb then S.use, S.useLabel, S.useT = a.piece, lb, 0.3 end
        elseif S.useT and S.useT > 0 and S.lastUse then S.use, S.useLabel = S.lastUse, S.lastLabel end
        S.useT = (S.useT or 0) - dt
        S.lastUse, S.lastLabel = S.use, S.useLabel
        usePrompt()
        return
    end
    if S.useShown then usePrompt() end
    if out > 15 or Game.GetMountedVehicle(Game.GetPlayer()) then exitBuild() return end
    if S.gz then timed("gizmo", Gizmo.tick) end
    do                                                          -- an animation's card in hand: the person it would go to is outlined
        local who = S.hold and byKey[S.hold.key].pose and aim().piece
        if who and not who.it.npc then who = nil end
        if S.poseAim ~= who then
            if S.poseAim then outlinePiece(S.poseAim, OUTLINE.off) end
            if who then outlinePiece(who, OUTLINE.target) end
            S.poseAim = who or nil
        end
    end
    if S.hold then
        if S.rot ~= 0 and (S.free or not byKey[S.hold.key].kind) then
            S.hold.yaw = (S.hold.yaw + S.rot * SPIN * dt) % 360
            if S.hold.q then S.hold.q = Q.norm(Q.mul(Q.yaw(S.rot * SPIN * dt), S.hold.q)) end
        end
        if S.target then outlinePiece(S.target, OUTLINE.off); S.target = nil end
        Lines.set("plant", nil)
        local o, yaw, ok = timed("placement", placement)
        S.place = { o = o, yaw = yaw, ok = ok }
        timed("ghost", syncGhost, o, yaw, ok, dt)
        if o and not S.free and not S.gz and byKey[S.hold.key].connect and S.showSnaps then
            Lines.set("snap", timed("snapdots", snapDots, byKey[S.hold.key], o, yaw))
        else Lines.set("snap", nil) end
    elseif S.gz and S.gz.piece then
        S.place = nil
        dropGhost()
    else
        Gizmo.off()
        S.place = nil
        dropGhost()
        local t = timed("aim", aim).piece
        retarget(t)
        Lines.set("snap", nil)
        Lines.set("plant", t and plant(t) and timed("plant", plantLines, t) or nil)
    end
end
registerForEvent("onUpdate", function(dt)
    World.drop()
    Eng.frame()
    Eng.slowFrame()
    timed("update", update, dt)
    Lines.flush()
end)

-- CET console: GetMod("Homestead").tp()    -> V to the settlement's south edge, facing it
--              GetMod("Homestead").popwatch() -> pieces despawned / spawned again to scripting.log (again: off)
--              GetMod("Homestead").info()  -> where V, the zone and the workbench are
--              GetMod("Homestead").build() -> workshop mode right here (testing)
--              GetMod("Homestead").reset() -> every piece of every settlement gone, workbenches too
local function tp()
    if S.zone == NOWHERE then return end
    Eng.teleport(Game.GetPlayer(), v4(S.zone.x, S.zone.y - RADIUS - 6, S.zone.z + 1), EulerAngles.new(0, 0, 0))
end
local function reset()
    exitBuild()
    refresh()
    local gone = {}
    for _, p in ipairs(S.pieces) do
        gone[hashOf(p.id)] = true
        for _, id in ipairs(p.parts or {}) do gone[hashOf(id)] = true end
        removePiece(p)
    end
    for _, tag in ipairs({ "Homestead", "Homestead.part" }) do
        for _, id in ipairs(des():GetTaggedIDs(tag) or {}) do if not gone[hashOf(id)] then gone[hashOf(id)] = true; del(id) end end
    end
    Life.reset()
    Life.navClear()
    refresh()
    log("all pieces removed")
end
local function info()
    local pos = playerPos()
    refresh()
    log(string.format("V at %.1f, %.1f, %.1f; zone centre %.0f, %.0f; in zone %s; workshop %s", pos.x, pos.y, pos.z, S.zone.x, S.zone.y, tostring(S.inZone), tostring(S.build)))
    for _, s in ipairs(Sites.list) do log(string.format("settlement %s at %.1f, %.1f%s", s.key, s.x, s.y, s == S.zone and " (here)" or "")) end
    log("dynamic entity system ready: " .. tostring(des():IsReady()) .. ", pieces " .. #S.pieces .. " (tagged " .. tostring(S.tagged) .. ")"
        .. ", bench tag populated: " .. tostring(des():IsPopulated("Homestead.bench")))
    if S.bench then
        local b = S.bench.at
        log(string.format("workbench at %.1f, %.1f, %.1f (%.1f m away), entity spawned: %s", b.x, b.y, b.z,
            math.sqrt((b.x - pos.x) ^ 2 + (b.y - pos.y) ^ 2), tostring(des():GetEntity(S.bench.id) ~= nil)))
    else log("no workbench") end
end

-- the dev table (GetMod("Homestead")): the console's commands, and what tools/sim.py and tools/dev read
return {
    tp = tp, info = info, build = enterBuild, exit = exitBuild, reset = reset, found = found, abandon = abandon,
    popwatch = Testing.popwatch, prof = Eng.prof, calls = Eng, state = S, key = onKey, refresh = refresh,
    placement = placement, startMove = startMove, restore = restore, aim = aim,
    sites = Sites, settings = Settings, anim = Anim, life = Life, keys = Keys, C = C, world = World,
    zone = function() return S.zone, tree, CATS end,
    picked = function() local e, n = picked() return e and e.name, S.sel[n] or 1, #n.kids end,
    pairs = function(a, b) return pairs_(Grid.named({ name = a }), Grid.named({ name = b })) end,
    gizmoView = function()
        local g, h = S.gz, S.hold
        local src = h or g.piece
        local hs, _, cs = Gizmo.handles(Gizmo.cam(), byKey[src.key], g.o, h and h.q or src.q or Q.yaw(src.yaw))
        return hs, cs
    end,
}
